import{_ as n,l as i,o as e,c as l,v as o,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"依赖混淆","description":"","frontmatter":{"title":"依赖混淆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dependency-confusion.md","filePath":"cs/dependency-confusion.md","lastUpdated":1789023840000}'),h={name:"cs/dependency-confusion.md"};function E(u,a,_,m,f,A){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="依赖混淆" tabindex="-1">依赖混淆 <a class="header-anchor" href="#依赖混淆" aria-label="Permalink to &quot;依赖混淆&quot;">​</a></h1><div class="epigraph"><p>包管理器按名字解析。内部包名若在公网可被同名抢注，构建可能拉到陌生人的版本。这是名字空间与源优先级问题，不是 AES 配错。</p><footer>—— 据 Birsan 对依赖混淆的公开报告；对照 npm/PyPI 的命名空间与作用域政策</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/sbom-reproducible-builds">SBOM</a>要你知道依赖是谁。缺口是<strong>解析</strong>：CI 可能先问公共登记。本课讲作用域、私有源优先、钉哈希，不提供抢注教程。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内部名 <code>company-logger</code> 未在公网占住，构建配置了公共源。解析器选了高版本的公共包。缺口是源策略与作用域（<code>@org/</code>）。</p><h3 id="钉版本不够" tabindex="-1">钉版本不够 <a class="header-anchor" href="#钉版本不够" aria-label="Permalink to &quot;钉版本不够&quot;">​</a></h3><p>要钉完整性哈希或供应商缓存。版本号可被抢先加。</p><p><span class="marginnote">Birsan 2021 公开报告。本课禁止对公共登记处的实验抢注。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列防御：命名空间、私有代理只镜像允许列表、--offline、哈希锁文件。对照 typosquatting：看错字母。下一课安全编码与审计把人审接上。</p>',12)),(e(),s(c,null,{default:t(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E5%8C%85%E5%90%8D%22%5D%20--%3E%20RES%5B%22%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20PUB%5B%22%E5%85%AC%E5%85%B1%E6%BA%90%22%5D%20--%3E%20RES%0A%20%20PRIV%5B%22%E7%A7%81%E6%9C%89%E6%BA%90%22%5D%20--%3E%20RES%0A%20%20POL%5B%22%E7%A7%81%E6%9C%89%E4%BC%98%E5%85%88%20%2F%20%E4%BD%9C%E7%94%A8%E5%9F%9F%22%5D%20--%3E%20SAFE%5B%22%E6%8B%89%E5%88%B0%E9%A2%84%E6%9C%9F%E5%8F%91%E5%B8%83%E8%80%85%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>供应链的解析层与 DNS 课同形：名字到物件的映射可被骗。下一课把编码标准与代码审查收成流程。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无抢注步骤。安全编码与审计下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SBOM 假设解析正确。</li><li>同名公共包可骗过 CI。</li><li>作用域、源优先级、哈希锁。</li><li>下一课安全编码与审计。</li><li>出处：Birsan, 依赖混淆公开报告；npm/PyPI 作用域文档。</li></ul>',8))])}const b=n(h,[["render",E]]);export{P as __pageData,b as default};
